  'Каникулы': 'Демалыс',
  'Карточка уйдёт в архив вместе с задачами, эссе и списком вузов. Записи журнала изменений останутся, а вернуть ученика можно на экране архива.': 'Карточка тапсырмаларымен, эсселерімен және ЖОО тізімімен бірге мұрағатқа жіберіледі. Өзгерістер журналындағы жазбалар сақталады, ал оқушыны мұрағат экранында қайтаруға болады.',
  'Карточка целиком: все домены, история правок. Данные за ученика вы не вносите — подтверждаете.': 'Карточка толық: барлық домен, өзгерістер тарихы. Оқушының орнына деректерді енгізбейсіз — растайсыз.',
