  'Кем приходится ученику': 'Оқушыға кім болып келеді',
  'Класс': 'Сынып',
  'Клетка рядом с отметкой; можно печатать цифрами. Итог четверти считается сам.': 'Баға қатысу белгісінің жанындағы ұяшыққа қойылады; сандармен теруге болады. Тоқсандық баға өзі есептеледі.',
  'Книга школы с листами «Сотрудники», «Группы», «Предметы», «Звонки», «Подгруппы», «Уроки». Сначала предпросмотр: база не меняется, пока не нажата «Применить». Повторный импорт того же файла ничего не удваивает.': '«Сотрудники», «Группы», «Предметы», «Звонки», «Подгруппы», «Уроки» парақтары бар мектеп кітабы. Алдымен алдын ала қарау: «Қолдану» басылмайынша база өзгермейді. Сол файлды қайта импорттау ештеңені екі еселемейді.',
