  'Колонка → поле → домен: из реестра соответствий': 'Баған → өріс → домен: сәйкестік тізілімінен',
  'Колонки распознаются по заголовку первой строки: почта ученика, ФИО родителя, кем приходится, телефон, почта, способ связи, примечание, основной. Обязательны первые две.': 'Бағандар бірінші жолдағы тақырып бойынша танылады: оқушы поштасы, ата-ананың аты-жөні, туыстығы, телефон, пошта, байланыс тәсілі, ескертпе, негізгі. Алғашқы екеуі міндетті.',
  'Колонки распознаются по заголовку первой строки: почта ученика, название соревнования, вид спорта, уровень, дата, результат, сертификат, ссылка. Обязательны первые две.': 'Бағандар бірінші жолдағы тақырып бойынша танылады: оқушы поштасы, жарыс атауы, спорт түрі, деңгей, күні, нәтиже, сертификат, сілтеме. Алғашқы екеуі міндетті.',
  'Колонки сопоставляются с полями стипендии: название, организатор, страна, уровень, тип финансирования, сумма, валюта, основания, дедлайн, ссылка, требования, описание. Обязательно название. Записи придут с плашкой «не подтверждено» — снимет её директор по поступлению, сверив со страницей стипендии.': 'Бағандар стипендия өрістерімен сәйкестендіріледі: атауы, ұйымдастырушы, ел, деңгей, қаржыландыру түрі, сома, валюта, негіздеме, дедлайн, сілтеме, талаптар, сипаттама. Атауы міндетті. Жазбалар «расталмаған» белгісімен түседі — түсу жөніндегі директор стипендия бетімен салыстырып, оны алып тастайды.',
  'Колонки сопоставляются с полями требований: вуз, программа, уровень, пороги IELTS/TOEFL/SAT/ACT/GPA, предметы, портфолио, примечания, ссылка. Обязательны вуз и программа. Записи придут с плашкой «не подтверждено» — снимет её директор по поступлению, сверив с сайтом.': 'Бағандар талап өрістерімен сәйкестендіріледі: ЖОО, бағдарлама, деңгей, IELTS/TOEFL/SAT/ACT/GPA шектік балдары, пәндер, портфолио, ескертпелер, сілтеме. ЖОО мен бағдарлама міндетті. Жазбалар «расталмаған» белгісімен түседі — түсу жөніндегі директор сайтпен салыстырып, оны алып тастайды.',
  'Колонки: exam_type, section, topic, difficulty, text, A, B, C, D, correct, explanation, source. Обязательны exam_type, section, topic, text и correct; вариантов ответа минимум два.': 'Бағандар: exam_type, section, topic, difficulty, text, A, B, C, D, correct, explanation, source. Міндетті: exam_type, section, topic, text және correct; жауап нұсқалары кемінде екеу.',
