  'Пока ни одного вида спорта. Заведите те, которыми занимаются ваши ученики: после этого вид спорта можно будет выбрать в профиле, а дашборд начнёт считать по видам.': 'Әзірге спорт түрі жоқ. Оқушыларыңыз айналысатын спорт түрлерін қосыңыз: содан кейін спорт түрін профильде таңдауға болады, ал дашборд спорт түрлері бойынша есептей бастайды.',
