  'Сначала проверка: база не меняется, пока не нажата «Применить». Повторная загрузка того же файла ничего не удваивает, новый файл переводит учеников с выбранной даты — прошлые оценки остаются в прежней подгруппе.': 'Алдымен тексеру: «Қолдану» басылмайынша база өзгермейді. Сол файлды қайта жүктеу ештеңені екі еселемейді, жаңа файл оқушыларды таңдалған күннен ауыстырады — бұрынғы бағалар бұрынғы топшада қалады.',
